profile:
query ZC_DiscordUserLookup($filter: UserFilter!) {
  users(first: 1, filter: $filter) {
    nodes {
      id
      steamId
      steamName
      discordId
      dateCreated
      userPoints {
        points
        rank
        totalPoints
        worldRecords
      }
      records(first: 0) {
        totalCount
      }
      personalBestGlobals(first: 0) {
        totalCount
      }
      worldRecordGlobals(first: 0) {
        totalCount
      }
      levelItems(first: 0, filter: { deleted: { equalTo: false } }) {
        totalCount
      }
      votes(first: 0) {
        totalCount
      }
    }
  }
}

autocomplete:
query ZC_DiscordLevelSearch($search: String!) {
  levels(
    first: 8
    filter: {
      publiclyVisible: { equalTo: true }
      levelItems: {
        some: {
          deleted: { equalTo: false }
          or: [
            { name: { includesInsensitive: $search } }
            { author: { steamName: { includesInsensitive: $search } } }
          ]
        }
      }
    }
    orderBy: [LEVEL_POINTS_POINTS_DESC, ID_ASC]
  ) {
    nodes {
      id
      xxHash
      levelItems(
        first: 1
        filter: { deleted: { equalTo: false } }
        orderBy: [UPDATED_AT_DESC]
      ) {
        nodes {
          name
          imageUrl
          author {
            steamName
          }
        }
      }
      levelPoints {
        points
        rating
      }
      votes(first: 0) {
        totalCount
      }
    }
  }
}

page:
query ZC_DiscordLevels($first: Int, $filter: LevelFilter!, $orderBy: [LevelsOrderBy!]) {
  levels(first: $first, filter: $filter, orderBy: $orderBy) {
    edges {
      node {
        ...ZC_DiscordPlaylistLevel
      }
    }
  }
}

fragment ZC_DiscordPlaylistLevel on Level {
  id
  xxHash
  publiclyVisible
  adventure
  dateCreated
  levelItems(
    first: 1
    filter: { deleted: { equalTo: false } }
    orderBy: [UPDATED_AT_DESC]
  ) {
    nodes {
      name
      imageUrl
      fileUid
      fileAuthor
      workshopId
      createdAt
      updatedAt
      author {
        id
        steamId
        steamName
        discordId
      }
    }
  }
  levelPoints {
    points
    rating
  }
  records(first: 0) {
    totalCount
  }
  personalBestGlobals(first: 0) {
    totalCount
  }
  votes(first: 0) {
    totalCount
  }
  worldRecordGlobal {
    record {
      time
    }
    user {
      id
      steamId
      steamName
      discordId
    }
  }
}

feed:
subscription ZC_DiscordActivityEventsLive {
  discordActivityEvents(first: 100, orderBy: [ID_DESC]) {
    nodes {
      id
      kind
      levelId
      userId
      previousUserId
      recordId
      previousRecordId
      payload
      occurredAt
      level {
        id
        xxHash
        levelItems(
          first: 1
          filter: { deleted: { equalTo: false } }
          orderBy: [UPDATED_AT_DESC]
        ) {
          nodes {
            name
            imageUrl
            workshopId
            author {
              id
              steamId
              steamName
              discordId
            }
          }
        }
        levelPoints {
          points
          rating
        }
        personalBestGlobals(first: 0) {
          totalCount
        }
      }
      user {
        id
        steamId
        steamName
        discordId
      }
      previousUser {
        id
        steamId
        steamName
        discordId
      }
      record {
        id
        time
        modVersion
      }
      previousRecord {
        id
        time
        modVersion
      }
    }
  }
}
